"""The project area (#692): project-owned roles and skills in `.mercury/local.json`, generated by the same renderers as the
pack roles and skill entries, recorded in the lock's own `local` section, adopted only with --adopt-local, retired by
removing the manifest entry. Also the role-source extensions (attribution, optional Codex fields) and the
`guard_write_actions` param. Nothing here touches the network."""
import hashlib
import importlib.util
import json
import os
import subprocess
import sys
import tempfile
import tomllib
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
TOOL = ROOT / "tools" / "mercury.py"
LOCK, CONFIG, LOCAL = ".mercury/lock.json", ".mercury/config.json", ".mercury/local.json"
WORKTREE_RUNNER = ("import importlib.util, sys; spec = importlib.util.spec_from_file_location('m', sys.argv[1]); "
                   "m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m); sys.exit(m.main(sys.argv[2:], worktree=True))")
ORIGIN = "https://github.com/test/mercury.git"
ATTRIBUTION = ("attribution: |\n  Based on example/agents (LICENSE: MIT) SHA: 0123456789abcdef0123456789abcdef01234567\n"
               "  Source: https://github.com/example/agents roles/analyst.md\n\n  Adapted for this project.\n")
ROLE = ("---\ndescription: \"Assess feasibility.\"\n" + ATTRIBUTION +
        "claude:\n  model: opus\n  disallowedTools: \"Edit, Write\"\ncodex:\n  sandbox_mode: read-only\n  web_search: disabled\n"
        "---\n\n# Role: analyst\n\nWeigh cost and risk.\n")
SKILL = "---\nname: proj-x\ndescription: Does the project thing.\nuser-invocable: true\n---\n\n# proj-x\n\nUse $ARGUMENTS here.\n"

try:
    import yaml  # PyYAML, installed in CI before these tests; optional locally
except ImportError:  # pragma: no cover
    yaml = None


def load_tool():
    spec = importlib.util.spec_from_file_location("mercury_tool_local", TOOL)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


T = load_tool()


def write(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data if isinstance(data, bytes) else data.encode("utf-8"))


def git(repo, *args):
    r = subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@example.com", *args],
                       capture_output=True, text=True, encoding="utf-8")
    assert r.returncode == 0, r.stderr
    return r.stdout


def frontmatter(text):
    assert text.startswith("---\n"), text[:40]
    return text.split("---\n", 2)[1]


class Base(unittest.TestCase):
    """A minimal Mercury source (core pack with one role) and a target with a project area."""

    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.tmp = Path(tmp.name)
        self.src, self.dst = self.tmp / "src", self.tmp / "dst"
        p = self.src / "packs"
        write(self.src / "mercury.json", json.dumps({"schema_version": 1, "packs": {"core": {"enabled": True, "required": True}}}))
        write(p / "core/pack.json", json.dumps({"schema_version": 1, "name": "core", "skills": {}}))
        write(p / "core/agents.md", "## Core\n\nCore text.\n")
        write(p / "core/claude.md", "@AGENTS.md\n")
        write(p / "core/roles/dev.md", "---\ndescription: \"Builds.\"\nclaude:\n  model: sonnet\ncodex:\n  sandbox_mode: workspace-write\n---\n\nbody\n")
        git(self.src.parent, "init", "-q", str(self.src))
        git(self.src, "config", "core.autocrlf", "false")
        git(self.src, "add", "-A")
        self.dst.mkdir()
        write(self.dst / CONFIG, json.dumps({"schema_version": 1, "packs": ["core"]}))

    def manifest(self, roles=None, skills=None):
        write(self.dst / LOCAL, json.dumps({"schema_version": 1, "roles": roles or {}, "skills": skills or {}}))

    def role(self, name="game-analyst", text=ROLE):
        write(self.dst / f".mercury/local/roles/{name}.md", text)

    def run_tool(self, mode, *extra):
        r = subprocess.run([sys.executable, "-B", "-c", WORKTREE_RUNNER, str(TOOL), mode, "--source", str(self.src),
                            "--target", str(self.dst), *extra], capture_output=True, text=True, encoding="utf-8")
        return r.returncode, r.stdout + r.stderr

    def apply(self, *extra):
        return self.run_tool("apply", *extra)

    def snapshot(self):
        return {p.relative_to(self.dst).as_posix(): p.read_bytes() for p in sorted(self.dst.rglob("*")) if p.is_file()}

    def lock(self):
        return json.loads((self.dst / LOCK).read_text(encoding="utf-8"))

    def standard(self):
        """One role and one skill whose source directory is the Codex entry location (so only Claude gets an entry)."""
        self.role()
        write(self.dst / ".agents/skills/proj-x/SKILL.md", SKILL)
        write(self.dst / ".agents/skills/proj-x/ref.md", "ref\n")
        self.manifest(roles={"game-analyst": ".mercury/local/roles/game-analyst.md"},
                      skills={"proj-x": {"path": ".agents/skills/proj-x", "hosts": ["claude", "codex"]}})


class Generation(Base):
    def test_role_and_skill_outputs_and_the_lock_section(self):
        self.standard()
        code, out = self.apply()
        self.assertEqual(code, 0, out)
        s = self.snapshot()
        md = s[".claude/agents/game-analyst.md"].decode()
        toml = s[".codex/agents/game-analyst.toml"].decode()
        stub = s[".claude/skills/proj-x/SKILL.md"].decode()
        # no prefix, both formats, the attribution at the top of both, verbatim
        self.assertTrue(toml.startswith("# Based on example/agents (LICENSE: MIT) SHA: 0123456789abcdef0123456789abcdef01234567\n"
                                        "# Source: https://github.com/example/agents roles/analyst.md\n#\n# Adapted for this project.\n"
                                        "# Generated by tools/mercury.py from .mercury/local/roles/game-analyst.md."), toml[:400])
        got = tomllib.loads(toml)
        self.assertEqual(got, {"name": "game-analyst", "description": "Assess feasibility.", "sandbox_mode": "read-only",
                               "web_search": "disabled", "developer_instructions": "# Role: analyst\n\nWeigh cost and risk.\n"})
        self.assertNotIn("model", got)  # the Codex model and effort are optional
        fm = frontmatter(md)
        self.assertIn('name: "game-analyst"', fm)
        if yaml is not None:
            self.assertEqual(yaml.safe_load(fm)["model"], "opus")
        self.assertIn("\n---\n\n<!--\nBased on example/agents (LICENSE: MIT)", md)
        self.assertEqual(md.count("-->"), 2)  # the attribution comment and the generated note
        # the skill: no entry where the source lives (Codex), a Claude entry that points at the declared directory
        self.assertEqual(s[".agents/skills/proj-x/SKILL.md"].decode(), SKILL)
        self.assertNotIn(".agents/skills/proj-x/SKILL.md", self.lock()["local"]["files"])
        self.assertIn("The full skill lives in `.agents/skills/proj-x/`", stub)
        self.assertIn("This skill belongs to the project", stub)
        self.assertIn("relative to the repository root", stub)  # a project skill's paths are not skill-relative
        self.assertIn("Markdown link stays relative to the file that contains it", stub)
        self.assertNotIn("Resolve every relative path", stub)
        self.assertIn("name: proj-x\n", stub)
        self.assertIn("user-invocable: true\n", stub)  # other frontmatter fields are carried, as for pack skills
        self.assertIn("Arguments: $ARGUMENTS", stub)
        if yaml is not None:
            self.assertEqual(yaml.safe_load(frontmatter(stub))["description"], "Does the project thing.")
        local = self.lock()["local"]
        self.assertEqual(sorted(local["files"]), [".claude/agents/game-analyst.md", ".claude/skills/proj-x/SKILL.md",
                                                  ".codex/agents/game-analyst.toml"])
        self.assertEqual(sorted(local["sources"]), [".agents/skills/proj-x/SKILL.md", LOCAL, ".mercury/local/roles/game-analyst.md"])
        self.assertNotIn(".claude/agents/game-analyst.md", self.lock()["files"])  # apart from the pack files
        self.assertEqual(self.run_tool("check")[0], 0)
        code, out = self.apply()
        self.assertIn("wrote 0, deleted 0", out)

    def test_the_stub_writer_and_the_role_renderer_are_the_pack_ones(self):
        # a pack skill entry is unchanged by the shared writer, and a role renders the same whichever area it comes from
        pack = T.stub_bytes("core", "alpha", "mercury-alpha", "Alpha.", [], "SKILL.md").decode()
        self.assertIn("This skill is installed by Mercury (pack `core`). The full skill lives in `.mercury/packs/core/skills/alpha/`.", pack)
        role = T.parse_role(ROLE.encode(), "t")
        a = T.role_outputs("x", ".mercury/packs/core/roles/x.md", role)
        b = T.role_outputs("x", ".mercury/local/roles/x.md", role)
        # Only the source path differs; the guard hooks point at .mercury/packs/core/hooks/ in both (#706).
        self.assertEqual({k: v.replace(b".mercury/packs/core/roles/", b".mercury/local/roles/") for k, v in a.items()}, b)

    def test_a_host_section_decides_which_files_exist(self):
        self.role(text=ROLE.replace("claude:\n  model: opus\n  disallowedTools: \"Edit, Write\"\n", ""))
        self.manifest(roles={"game-analyst": ".mercury/local/roles/game-analyst.md"})
        self.assertEqual(self.apply()[0], 0)
        self.assertFalse((self.dst / ".claude/agents/game-analyst.md").exists())
        self.assertTrue((self.dst / ".codex/agents/game-analyst.toml").exists())

    def test_a_project_role_may_leave_the_codex_sandbox_to_the_session(self):
        text = ROLE.replace("  sandbox_mode: read-only\n", "")
        with self.assertRaises(T.BuildError):  # a pack role still needs it
            T.parse_role(text.encode(), "t")
        self.role(text=text)
        self.manifest(roles={"game-analyst": ".mercury/local/roles/game-analyst.md"})
        self.assertEqual(self.apply()[0], 0)
        got = tomllib.loads((self.dst / ".codex/agents/game-analyst.toml").read_text(encoding="utf-8"))
        self.assertNotIn("sandbox_mode", got)
        self.assertEqual(got["web_search"], "disabled")

    def test_a_skill_elsewhere_gets_an_entry_per_host(self):
        write(self.dst / "tools/skills/proj-x/SKILL.md", SKILL)
        self.manifest(skills={"proj-x": {"path": "tools/skills/proj-x", "hosts": ["codex", "claude"]}})
        self.assertEqual(self.apply()[0], 0)
        for root in (".agents/skills", ".claude/skills"):
            self.assertIn("`tools/skills/proj-x/`", (self.dst / root / "proj-x/SKILL.md").read_text(encoding="utf-8"))


class Attribution(unittest.TestCase):
    def render(self, attribution_line):
        text = ROLE.replace(ATTRIBUTION, attribution_line)
        role = T.parse_role(text.encode(), "t")
        return T.role_outputs("r", ".mercury/local/roles/r.md", role)

    def test_newline_followed_by_toml_cannot_add_a_key(self):
        out = self.render('attribution: "MIT\\n[evil]\\nsandbox_mode = \\"danger-full-access\\"\\n\'\'\'"\n')
        got = tomllib.loads(out[".codex/agents/r.toml"].decode())
        self.assertEqual(got["sandbox_mode"], "read-only")
        self.assertNotIn("evil", got)
        self.assertTrue(out[".codex/agents/r.toml"].decode().startswith("# MIT\n# [evil]\n# sandbox_mode ="))

    def test_comment_breakers_and_hidden_characters_are_refused(self):
        for bad in ('"MIT --> <script>"', '"x <!-- y"', '"a --!> b"', '"a\\rb"', '"a\\u2028b"', '"a\\u202eb"', '"a\\u000bb"',
                    '"a\\u0000b"', '""', "plain words", "|\n  ok\n  then --> out"):
            with self.subTest(bad=bad):
                with self.assertRaises(T.BuildError):
                    T.parse_role(ROLE.replace(ATTRIBUTION, f"attribution: {bad}\n").encode(), "t")
        with self.assertRaises(T.BuildError):
            T.parse_role(ROLE.replace(ATTRIBUTION, "attribution: |\n" + "  x\n" * 21).encode(), "t")
        with self.assertRaises(T.BuildError):  # declared twice
            T.parse_role(ROLE.replace(ATTRIBUTION, ATTRIBUTION + 'attribution: "again"\n').encode(), "t")

    def test_a_tab_and_unicode_text_stay_verbatim(self):
        out = self.render('attribution: "Copyright \\u00a9 2024 Jos\\u00e9\\tand others"\n')
        self.assertIn("# Copyright \u00a9 2024 Jos\u00e9\tand others\n", out[".codex/agents/r.toml"].decode())
        self.assertIn("<!--\nCopyright \u00a9 2024 Jos\u00e9\tand others\n-->", out[".claude/agents/r.md"].decode())


class Validation(Base):
    def assertRefused(self, text=None):
        before = self.snapshot()
        code, out = self.apply()
        self.assertEqual(code, 2, out)
        if text:
            self.assertIn(text, out)
        self.assertEqual(self.snapshot(), before)

    def test_names(self):
        for name in ("mercury-x", "Game", "1x", "a_b", "x" * 65, "a.b", ""):
            with self.subTest(name=name):
                self.manifest(roles={name: f".mercury/local/roles/{name}.md"})
                self.assertRefused()
                self.manifest(skills={name: {"path": "s/x", "hosts": ["claude"]}})
                self.assertRefused()

    def test_role_source_must_be_the_fixed_path(self):
        self.role()
        for rel in (".mercury/local/roles/other.md", "roles/game-analyst.md", ".mercury/packs/core/roles/dev.md", 5):
            with self.subTest(rel=rel):
                self.manifest(roles={"game-analyst": rel})
                self.assertRefused("must be .mercury/local/roles/game-analyst.md")

    def test_manifest_shape(self):
        for doc in ({"schema_version": 2}, {"schema_version": 1, "other": {}}, {"schema_version": 1, "roles": []}, [1], "x"):
            with self.subTest(doc=doc):
                write(self.dst / LOCAL, json.dumps(doc))
                self.assertRefused(LOCAL)
        write(self.dst / LOCAL, "{not json")
        self.assertRefused()

    def test_skill_paths_and_hosts(self):
        write(self.dst / "s/proj-x/SKILL.md", SKILL)
        write(self.dst / ".mercury/packs/core/skills/proj-x/SKILL.md", SKILL)
        write(self.dst / ".claude/skills/other/SKILL.md", SKILL)
        write(self.dst / ".claude/skills/mercury-proj-x/SKILL.md", SKILL)
        cases = {
            "managed-packs": {"path": ".mercury/packs/core/skills/proj-x", "hosts": ["claude"]},
            "managed-case": {"path": ".Mercury/Packs/core/skills/proj-x", "hosts": ["claude"]},
            "managed-stub": {"path": ".claude/skills/mercury-proj-x", "hosts": ["codex"]},
            "other-name-under-root": {"path": ".claude/skills/other", "hosts": ["codex"]},
            "dotdot": {"path": "s/../s/proj-x", "hosts": ["claude"]},
            "absolute": {"path": "/s/proj-x", "hosts": ["claude"]},
            "drive": {"path": "C:/s/proj-x", "hosts": ["claude"]},
            "git": {"path": ".git/proj-x", "hosts": ["claude"]},
            "missing": {"path": "s/none", "hosts": ["claude"]},
            "no-hosts": {"path": "s/proj-x", "hosts": []},
            "bad-host": {"path": "s/proj-x", "hosts": ["cursor"]},
            "dup-host": {"path": "s/proj-x", "hosts": ["claude", "claude"]},
            "extra-key": {"path": "s/proj-x", "hosts": ["claude"], "entry": "x.md"},
        }
        for case, spec in cases.items():
            with self.subTest(case=case):
                self.manifest(skills={"proj-x": spec})
                self.assertRefused()
        write(self.dst / "s/other/SKILL.md", SKILL)  # declares the name proj-x
        self.manifest(skills={"other": {"path": "s/other", "hosts": ["claude"]}})
        self.assertRefused("names itself")

    @unittest.skipIf(os.name == "nt", "creating a symbolic link needs a privilege on Windows")
    def test_links_are_refused_for_sources_and_outputs(self):
        write(self.tmp / "outside/proj-x/SKILL.md", SKILL)
        os.symlink(self.tmp / "outside/proj-x", self.dst / "linked")
        self.manifest(skills={"proj-x": {"path": "linked", "hosts": ["claude"]}})
        self.assertRefused("link")
        write(self.tmp / "outside/role.md", ROLE)
        (self.dst / ".mercury/local/roles").mkdir(parents=True)
        os.symlink(self.tmp / "outside/role.md", self.dst / ".mercury/local/roles/game-analyst.md")
        self.manifest(roles={"game-analyst": ".mercury/local/roles/game-analyst.md"})
        self.assertRefused()
        (self.dst / ".mercury/local/roles/game-analyst.md").unlink()
        self.role()
        (self.dst / ".claude").mkdir()
        os.symlink(self.tmp / "outside", self.dst / ".claude/agents")
        self.assertRefused("link")
        self.assertEqual(sorted(p.name for p in (self.tmp / "outside").iterdir()), ["proj-x", "role.md"])

    def test_a_bad_role_source_writes_nothing(self):
        self.manifest(roles={"game-analyst": ".mercury/local/roles/game-analyst.md"})
        for text in (ROLE.replace("sandbox_mode: read-only", "sandbox_mode: danger-full-access"),
                     ROLE.replace("claude:\n  model: opus\n", "claude:\n  colour: red\n"), ROLE.replace("Weigh", "'''Weigh")):
            with self.subTest(text=text[-60:]):
                self.role(text=text)
                self.assertRefused()


class Lifecycle(Base):
    def test_an_existing_file_needs_adopt_local_and_otherwise_nothing_is_written(self):
        self.standard()
        write(self.dst / ".codex/agents/game-analyst.toml", "# the project's hand-written role\nname = \"game-analyst\"\n")
        before = self.snapshot()
        code, out = self.apply()
        self.assertEqual(code, 1, out)
        self.assertIn("--adopt-local", out)
        self.assertEqual(self.snapshot(), before)  # zero writes: not even the other outputs or the lock
        code, out = self.apply("--adopt-local")
        self.assertEqual(code, 0, out)
        self.assertIn("Generated by tools/mercury.py", (self.dst / ".codex/agents/game-analyst.toml").read_text(encoding="utf-8"))
        self.assertEqual(self.run_tool("check")[0], 0)

    def test_adopt_local_is_only_for_install_and_apply_and_never_takes_a_link_or_a_hand_edit(self):
        self.standard()
        self.assertEqual(self.run_tool("check", "--adopt-local")[0], 2)  # argparse: unknown option for check
        self.assertEqual(self.apply()[0], 0)
        write(self.dst / ".claude/agents/game-analyst.md", "hand edit\n")
        before = self.snapshot()
        code, out = self.apply("--adopt-local")
        self.assertEqual(code, 1, out)
        self.assertIn("modified by hand", out)
        self.assertEqual(self.snapshot(), before)

    def test_a_directory_at_an_output_path_is_a_conflict_even_with_adopt_local(self):
        self.standard()
        (self.dst / ".claude/agents/game-analyst.md").mkdir(parents=True)
        before = self.snapshot()
        code, out = self.apply("--adopt-local")
        self.assertEqual(code, 1, out)
        self.assertIn("not a regular file", out)
        self.assertEqual(self.snapshot(), before)

    def test_update_follows_the_source_and_retire_deletes_only_recorded_outputs(self):
        self.standard()
        self.assertEqual(self.apply()[0], 0)
        self.role(text=ROLE.replace("Weigh cost and risk.", "Weigh cost, risk and time."))
        code, out = self.check_and_apply()
        self.assertIn("update: .claude/agents/game-analyst.md (project area)", out)
        self.assertIn("time.", (self.dst / ".codex/agents/game-analyst.toml").read_text(encoding="utf-8"))
        # unrelated project files at the same kind of location are never touched by a retire
        write(self.dst / ".claude/agents/own.md", "mine\n")
        write(self.dst / ".claude/skills/own/SKILL.md", "mine\n")
        self.manifest()  # retire everything
        code, out = self.apply()
        self.assertEqual(code, 0, out)
        self.assertIn("deleted 3", out)
        for rel in (".claude/agents/game-analyst.md", ".codex/agents/game-analyst.toml", ".claude/skills/proj-x"):
            self.assertFalse((self.dst / rel).exists(), rel)
        for rel in (".claude/agents/own.md", ".claude/skills/own/SKILL.md", ".agents/skills/proj-x/SKILL.md",
                    ".agents/skills/proj-x/ref.md", ".mercury/local/roles/game-analyst.md", LOCAL):
            self.assertTrue((self.dst / rel).exists(), rel)  # sources and the project's own files stay
        self.assertTrue((self.dst / ".claude/skills").is_dir())
        self.assertEqual(self.lock()["local"], {"files": {}, "sources": {LOCAL: self.lock()["local"]["sources"][LOCAL]}})
        (self.dst / LOCAL).unlink()
        self.assertEqual(self.apply()[0], 0)
        self.assertNotIn("local", self.lock())

    def check_and_apply(self):
        code, out = self.run_tool("check")
        self.assertEqual(code, 1, out)
        code2, out2 = self.apply()
        self.assertEqual(code2, 0, out2)
        return code, out

    def test_a_hand_edited_output_stops_update_and_retire(self):
        self.standard()
        self.apply()
        write(self.dst / ".codex/agents/game-analyst.toml", "edited\n")
        self.role(text=ROLE.replace("Weigh", "Assess"))
        before = self.snapshot()
        self.assertEqual(self.apply()[0], 1)
        self.assertEqual(self.snapshot(), before)
        self.manifest()
        before = self.snapshot()
        code, out = self.apply()
        self.assertEqual(code, 1, out)
        self.assertIn("retired from .mercury/local.json but modified by hand", out)
        self.assertEqual(self.snapshot(), before)

    def test_a_former_output_that_became_the_source_is_never_deleted(self):
        write(self.dst / "s/proj-x/SKILL.md", SKILL)
        self.manifest(skills={"proj-x": {"path": "s/proj-x", "hosts": ["claude", "codex"]}})
        self.assertEqual(self.apply()[0], 0)
        stub = (self.dst / ".agents/skills/proj-x/SKILL.md").read_bytes()
        # the project moves the skill to where Codex reads it; the old entry there is replaced by the real skill
        (self.dst / "s/proj-x/SKILL.md").unlink()
        write(self.dst / ".agents/skills/proj-x/SKILL.md", SKILL)
        self.manifest(skills={"proj-x": {"path": ".agents/skills/proj-x", "hosts": ["claude", "codex"]}})
        code, out = self.apply()
        self.assertEqual(code, 0, out)
        self.assertEqual((self.dst / ".agents/skills/proj-x/SKILL.md").read_text(encoding="utf-8"), SKILL)
        self.assertNotEqual(stub, SKILL.encode())
        self.assertNotIn(".agents/skills/proj-x/SKILL.md", self.lock()["local"]["files"])

    def test_a_tampered_local_section_cannot_steer_a_deletion(self):
        self.standard()
        self.apply()
        victims = ("src/app.py", ".claude/agents/mercury-dev.md", ".mercury/packs/core/agents.md", "AGENTS.md",
                   ".claude/agents/sub/x.md", ".claude/agents/X.md", ".claude/skills/x/other.md", ".mercury/local/roles/game-analyst.md")
        for victim in victims:
            with self.subTest(victim=victim):
                if not (self.dst / victim).exists():
                    write(self.dst / victim, "keep\n")
                data = self.lock()
                data["local"]["files"][victim] = hashlib.sha256((self.dst / victim).read_bytes()).hexdigest()
                (self.dst / LOCK).write_text(json.dumps(data), encoding="utf-8")
                before = self.snapshot()
                code, out = self.apply()
                self.assertEqual(code, 2, out)
                self.assertEqual(self.snapshot(), before)
                del data["local"]["files"][victim]
                (self.dst / LOCK).write_text(json.dumps(data), encoding="utf-8")


class CommitMode(unittest.TestCase):
    """External target: the packs come from a Mercury commit, the project area from the target's working tree."""

    def test_sources_are_read_from_the_target_and_install_takes_adopt_local(self):
        with tempfile.TemporaryDirectory() as tmp:
            src, dst = Path(tmp) / "src", Path(tmp) / "dst"
            for repo in (src, dst):
                repo.mkdir()
                git(repo, "init", "-q")
                git(repo, "config", "core.autocrlf", "false")
            git(src, "remote", "add", "origin", ORIGIN)
            write(src / "mercury.json", json.dumps({"schema_version": 1, "packs": {"core": {"enabled": True, "required": True}}}))
            write(src / "packs/core/pack.json", json.dumps({"schema_version": 1, "name": "core", "skills": {}}))
            write(src / "packs/core/agents.md", "## Core\n")
            write(src / "packs/core/claude.md", "@AGENTS.md\n")
            git(src, "add", "-A")
            git(src, "commit", "-q", "-m", "c1")
            git(src, "update-ref", "refs/remotes/origin/master", "HEAD")
            write(src / "packs/core/agents.md", "## Core, uncommitted\n")  # the working tree of Mercury never counts
            write(dst / ".mercury/local/roles/game-analyst.md", ROLE)
            write(dst / ".codex/agents/game-analyst.toml", "# old hand-written copy\n")
            write(dst / LOCAL, json.dumps({"schema_version": 1, "roles": {"game-analyst": ".mercury/local/roles/game-analyst.md"}}))
            run = lambda *a: subprocess.run([sys.executable, "-B", str(TOOL), *a, "--source", str(src), "--target", str(dst)],
                                            capture_output=True, text=True, encoding="utf-8")
            r = run("install")
            self.assertEqual(r.returncode, 1, r.stdout + r.stderr)
            self.assertFalse((dst / LOCK).exists())
            r = run("install", "--adopt-local")
            self.assertEqual(r.returncode, 0, r.stdout + r.stderr)
            self.assertIn("Weigh cost and risk.", (dst / ".codex/agents/game-analyst.toml").read_text(encoding="utf-8"))
            self.assertNotIn("uncommitted", (dst / "AGENTS.md").read_text(encoding="utf-8"))
            write(dst / ".gitignore", ".mercury/local/\n")  # an ignored source would never reach a commit
            r = run("check")
            self.assertEqual(r.returncode, 2, r.stdout + r.stderr)
            self.assertIn(".mercury/local/roles/game-analyst.md", r.stderr)


class GuardActionsParam(Base):
    def set_params(self, params):
        write(self.dst / CONFIG, json.dumps({"schema_version": 1, "packs": ["core"], "params": params}))

    def test_validation(self):
        ok = {"guard_write_scripts": ["deploy.sh"], "guard_write_actions": {"sot-worktree.ps1": ["Create", "Remove"],
                                                                            "sot-memory.ps1": ["Write"]}}
        self.set_params(ok)
        self.assertEqual(self.apply()[0], 0)
        many = {f"s{i}.ps1": ["A"] for i in range(21)}
        bad = [
            {"guard_write_actions": []}, {"guard_write_actions": {}}, {"guard_write_actions": many},
            {"guard_write_actions": {"dir/x.ps1": ["A"]}}, {"guard_write_actions": {"x.cmd": ["A"]}},
            {"guard_write_actions": {"x.ps1\n": ["A"]}}, {"guard_write_actions": {"x.ps1": []}},
            {"guard_write_actions": {"x.ps1": "Create"}}, {"guard_write_actions": {"x.ps1": ["1x"]}},
            {"guard_write_actions": {"x.ps1": ["a-b"]}}, {"guard_write_actions": {"x.ps1": ["$x"]}},
            {"guard_write_actions": {"x.ps1": ["Create", "create"]}}, {"guard_write_actions": {"x.ps1": ["A"] * 0 + [f"A{i}" for i in range(21)]}},
            {"guard_write_actions": {"x.ps1": ["A"], "X.ps1": ["B"]}},
            {"guard_write_scripts": ["Deploy.ps1"], "guard_write_actions": {"deploy.ps1": ["A"]}},
            {"guard_write_scripts": ["x.sh\n"]},
            {"guard_write_actions": {"git-safe.ps1": ["Status"]}}, {"guard_write_actions": {"Lane-Close.SH": ["A"]}},
        ]
        for params in bad:
            with self.subTest(params=params):
                self.set_params(params)
                code, out = self.apply()
                self.assertEqual(code, 2, out)
                self.assertIn("params.guard_write_", out)
        for params in ({"guard_write_actions": {"git-safe.ps1": ["Status"]}}, {"guard_write_actions": {"Lane-Close.sh": ["A"]}}):
            with self.subTest(built_in=params):
                self.set_params(params)
                code, out = self.apply()
                self.assertEqual(code, 2, out)
                self.assertIn("built-in list", out)

    def test_the_built_in_list_matches_the_guard(self):
        spec = importlib.util.spec_from_file_location("guard_for_test", ROOT / "packs/core/hooks/readonly_guard.py")
        guard = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(guard)
        self.assertEqual(T.GUARD_BUILTIN_SCRIPTS, frozenset(guard.WRITE_SCRIPTS))
        self.assertEqual(T.SCRIPT_RE.pattern, guard.SCRIPT_NAME.pattern)


class SkipSkillsParam(Base):
    """params.skip_skills leaves out a pack skill's entry files, for a project whose own skill does the job (#703)."""

    def setUp(self):
        super().setUp()
        p = self.src / "packs"
        write(p / "core/pack.json", json.dumps({"schema_version": 1, "name": "core",
                                                "skills": {"hand-off": {"hosts": ["claude", "codex"]}}}))
        write(p / "core/skills/hand-off/SKILL.md", '---\nname: hand-off\ndescription: "Hands off."\n---\n\nbody\n')
        git(self.src, "add", "-A")

    def set_params(self, params):
        write(self.dst / CONFIG, json.dumps({"schema_version": 1, "packs": ["core"], "params": params}))

    def test_a_skipped_skill_gets_no_entry_and_a_dropped_skip_restores_it(self):
        self.assertEqual(self.apply()[0], 0)
        entries = [".claude/skills/mercury-hand-off/SKILL.md", ".agents/skills/mercury-hand-off/SKILL.md"]
        for rel in entries:
            self.assertTrue((self.dst / rel).is_file(), rel)
        self.set_params({"skip_skills": ["hand-off"]})
        code, out = self.apply()
        self.assertEqual(code, 0, out)
        for rel in entries:
            self.assertFalse((self.dst / rel).exists(), rel)
        self.assertTrue((self.dst / ".mercury/packs/core/skills/hand-off/SKILL.md").is_file())
        self.set_params({})
        self.assertEqual(self.apply()[0], 0)
        for rel in entries:
            self.assertTrue((self.dst / rel).is_file(), rel)

    def test_validation(self):
        for params in ({"skip_skills": "hand-off"}, {"skip_skills": ["a/b"]}, {"skip_skills": ["hand-off", "hand-off"]},
                       {"skip_skills": ["no-such-skill"]}):
            with self.subTest(params=params):
                self.set_params(params)
                code, out = self.apply()
                self.assertEqual(code, 2, out)
                self.assertIn("params.skip_skills", out)


if __name__ == "__main__":
    unittest.main()
